// <auto-generated/>
namespace Fanex.Tarus.VirtualSport.Controllers.Customer.PTSetting
{
    using System;
    using System.Collections.Generic;
    using Fanex.Tarus.Web.Controllers;
    using Fanex.PTVirtualSports.Services;
    using System.Web.Mvc;
    using Newtonsoft.Json;
    using Newtonsoft.Json.Serialization;
    using Fanex.PTEngine.BusinessObjects;    
    using Fanex.Tarus.VirtualSport.Helpers;
    using Fanex.PTVirtualSports.Utilities;

    public class PTSettingBaseController : BaseController
    {
        protected static ICustomerService _customerService;
        public PTSettingBaseController(ICustomerService customerService)
        {            
            _customerService = customerService ?? new CustomerService();
        }

        public PTSettingBaseController(): this(null)
        {
        }

        [NonAction]
        protected JsonSerializerSettings GetJsonSerializerSetting()
        {
            JsonSerializerSettings settings = new JsonSerializerSettings();
            settings.NullValueHandling = NullValueHandling.Ignore;
            settings.ContractResolver = new CamelCasePropertyNamesContractResolver();
            return settings;
        }

        [NonAction]
        protected ICustomer DeserializeJsonString(string customerString)
        {
            JsonSerializerSettings settings = new JsonSerializerSettings();
            settings.NullValueHandling = NullValueHandling.Ignore;
           Customer customer = 
                JsonConvert.DeserializeObject<Customer>(customerString, settings);
            return customer;
        }



        protected IList<Result> ParseResult(Fanex.PTVirtualSports.BusinessObjects.VSResult Results)
        {
            IList<Result> results = new List<Result>();

            //1.Status
            foreach (Result result in Results.ResultStatus) 
            {
                if (result.ErrorCode == "0")
                {
                    results.Add(new Result()
                    {
                        ErrorCode = "-100",
                        ErrorMessage = Resource.GetResourceByKey("UpdateStatusSuccess")
                    });
                }
                else {
                    results.Add(result);
                }
                
            }

            //2.BetSetting
            foreach (Fanex.PTVirtualSports.BusinessObjects.Result result in Results.ResultBetSetting)
            {
                result.ErrorCode = result.ErrorCode.Replace("101", "104");//minbet,maxbet
                result.ErrorCode = result.ErrorCode.Replace("102", "105");//Max Per Match            
                if (Convert.ToInt32(result.ErrorCode) < 0)
                {
                    
                    string key = "_" + Convert.ToInt32(result.ErrorCode) * (-1);
                    result.ErrorMessage = CacheRef.GetSportName(result.SportTypeId) + " - " + Resource.GetResourceByKey(key);
                }       

                

                results.Add(result);
            }

            //3.PT
            foreach (Fanex.PTVirtualSports.BusinessObjects.Result result in Results.ResultPT)
            {        
                if (Convert.ToInt32(result.ErrorCode) < 0)
                {
                    string key = "_" + Convert.ToInt32(result.ErrorCode) * (-1);
                    result.ErrorMessage = CacheRef.GetSportName(result.SportTypeId) + " - " + Resource.GetResourceByKey(key);
                }
                else if (result.ErrorCode == "99")//Super edit pt on member
                {
                    result.ErrorMessage = CacheRef.GetSportName(result.SportTypeId) + " - " + Resource.GetResourceByKey("SuperMustGetAutoOnMember");
                }
                else if (result.ErrorCode == "98")//Master edit pt on member
                {
                    result.ErrorMessage = CacheRef.GetSportName(result.SportTypeId) + " - " + Resource.GetResourceByKey("MasterMustGetAutoOnMember");
                }
                else
                {
                    result.ErrorMessage = CacheRef.GetSportName(result.SportTypeId) + " - " + result.ErrorMessage;
                }

                results.Add(result);
            }

            if (results.Count == 0)
            {
                results.Add(new Fanex.PTVirtualSports.BusinessObjects.Result()
                { 
                    ErrorCode = "100",
                    ErrorMessage = Resource.GetResourceByKey("Unchanged")

                });
            }

            return results;
        }
    }
}
